router = APIRouter()

@router.get("/holdings/{id}", response_model=Holding)
async def get_holding(id: int):
    db = connect()
    holding = db.execute("SELECT * FROM active_holdings WHERE id = ?", (id,)).fetchone()
    if not holding:
        raise HTTPException(status_code=404, detail="Holding not found")
    return Holding(**holding)

@router.put("/holdings/{id}", response_model=Holding)
async def update_holding(id: int, data: Holding):
    db = connect()
    db.execute("UPDATE active_holdings SET name = ?, quantity = ?, price = ? WHERE id = ?", (data.name, data.quantity, data.price, id))
    db.commit()
    return get_holding(id)

@router.delete("/holdings/{id}", response_model=Holding)
async def delete_holding(id: int):
    db = connect()
    holding = db.execute("SELECT * FROM active_holdings WHERE id = ?", (id,)).fetchone()
    if not holding:
        raise HTTPException(status_code=404, detail="Holding not found")
    if holding['lots_count'] > 0:
        raise HTTPException(status_code=409, detail="Cannot delete holding with lots")
    db.execute("DELETE FROM active_holdings WHERE id = ?", (id,))
